$tournamentId..validate:
// Musi mieć wymagane pola
newData.hasChildren(['code', 'name', 'mode', 'level', 'status', 'host', 'createdAt'])

// Kod musi być 6-znakowy i zgodny z kluczem
&& newData.child('code').isString()
&& newData.child('code').val().length == 6
&& newData.child('code').val() == $tournamentId

// Nazwa max 50 znaków
&& newData.child('name').isString()
&& newData.child('name').val().length <= 50

// Tryb: tylko dozwolone wartości
&& newData.child('mode').val().matches(/^(groups|knockout)$/)

// Poziom: tylko dozwolone wartości
&& newData.child('level').val().matches(/^(easy|medium|hard|master)$/)

// Status: tylko dozwolone wartości
&& newData.child('status').val().matches(/^(lobby|groups|knockout|finished)$/)

// Host musi być stringiem
&& newData.child('host').isString()

// Punkty do wygrania: 1-10
&& (!newData.hasChild('pointsToWin') || (
  newData.child('pointsToWin').isNumber()
  && newData.child('pointsToWin').val() >= 1
  && newData.child('pointsToWin').val() <= 10
))

// Liczba grup: 0-8
&& (!newData.hasChild('groupCount') || (
  newData.child('groupCount').isNumber()
  && newData.child('groupCount').val() >= 0
  && newData.child('groupCount').val() <= 8
))
